            f = f * f * (3.0 - 2.0 * f);

            float a = BackdropHash21(i);
            float b = BackdropHash21(i + float2(1.0, 0.0));
            float c = BackdropHash21(i + float2(0.0, 1.0));
            float d = BackdropHash21(i + float2(1.0, 1.0));
            return lerp(lerp(a, b, f.x), lerp(c, d, f.x), f.y);
