            float2 localPx = localUV * float2(sourceWidth, sourceHeight);
            float2 fullResolution = max(float2(backdropW, backdropH), float2(1.0, 1.0));
            float2 uv = localPx / fullResolution;

            float2 p = uv - 0.5;
            p.x *= fullResolution.x / fullResolution.y;

